/**
 * Model Country
 * 
 */
export type Country = $Result.DefaultSelection<Prisma.$CountryPayload>
/**
 * Model City
 * 
 */
export type City = $Result.DefaultSelection<Prisma.$CityPayload>
/**
 * Model User
 * 
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Session
 * 
 */
export type Session = $Result.DefaultSelection<Prisma.$SessionPayload>
/**
 * Model MfaRecoveryCode
 * Code de secours de la double authentification : sert une fois, quand le
 * téléphone est perdu. Jamais stocké en clair.
 */
export type MfaRecoveryCode = $Result.DefaultSelection<Prisma.$MfaRecoveryCodePayload>
/**
 * Model VerificationToken
 * Codes à usage unique : OTP d'inscription, vérification d'e-mail,
 * réinitialisation de mot de passe.
 * 
 * Le code n'est **jamais stocké en clair** : une fuite de la base donnerait
 * sinon un accès immédiat à tous les comptes en cours de vérification. Le
 * compteur de tentatives ferme la porte au balayage des 10 000 combinaisons
 * d'un code à quatre chiffres.
 */
export type VerificationToken = $Result.DefaultSelection<Prisma.$VerificationTokenPayload>
/**
 * Model TermsAcceptance
 * Acceptation des CGU horodatée et versionnée — exigence du § 15 du cahier.
 */
export type TermsAcceptance = $Result.DefaultSelection<Prisma.$TermsAcceptancePayload>
/**
 * Model Address
 * 
 */
export type Address = $Result.DefaultSelection<Prisma.$AddressPayload>
/**
 * Model MakerProfile
 * Le cahier client sépare explicitement informations publiques et privées.
 * Cette frontière n'est pas qu'un choix d'affichage : aucune route ne doit
 * jamais exposer un champ marqué « privé » à un client.
 */
export type MakerProfile = $Result.DefaultSelection<Prisma.$MakerProfilePayload>
/**
 * Model KycDocument
 * 
 */
export type KycDocument = $Result.DefaultSelection<Prisma.$KycDocumentPayload>
/**
 * Model CourierProfile
 * 
 */
export type CourierProfile = $Result.DefaultSelection<Prisma.$CourierProfilePayload>
/**
 * Model VehicleRate
 * Grille tarifaire et capacités, par pays et par type de véhicule.
 * C'est cette table qui pilote le choix automatique du véhicule.
 */
export type VehicleRate = $Result.DefaultSelection<Prisma.$VehicleRatePayload>
/**
 * Model Category
 * 
 */
export type Category = $Result.DefaultSelection<Prisma.$CategoryPayload>
/**
 * Model Product
 * Pas de table de variantes : le cahier client décrit un produit avec un prix
 * et une quantité, sans déclinaison. Prix et stock vivent donc ici.
 * Réintroductible plus tard sans casse (cf. SPEC-ALIGNEMENT § 5).
 */
export type Product = $Result.DefaultSelection<Prisma.$ProductPayload>
/**
 * Model ProductImage
 * Le cahier client impose entre 3 et 5 photos par produit. La règle est
 * appliquée au moment de la soumission à modération, pas par le schéma :
 * un brouillon doit pouvoir n'en avoir aucune.
 */
export type ProductImage = $Result.DefaultSelection<Prisma.$ProductImagePayload>
/**
 * Model Cart
 * 
 */
export type Cart = $Result.DefaultSelection<Prisma.$CartPayload>
/**
 * Model CartItem
 * 
 */
export type CartItem = $Result.DefaultSelection<Prisma.$CartItemPayload>
/**
 * Model Order
 * 
 */
export type Order = $Result.DefaultSelection<Prisma.$OrderPayload>
/**
 * Model SubOrder
 * Un panier peut réunir les pièces de plusieurs créateurs. La sous-commande
 * est l'unité que le créateur voit, accepte et prépare, et l'unité sur
 * laquelle porte son versement.
 */
export type SubOrder = $Result.DefaultSelection<Prisma.$SubOrderPayload>
/**
 * Model OrderLine
 * Toutes les valeurs sont figées par copie : un créateur qui augmente ses
 * prix ou renomme une pièce ne doit pas pouvoir réécrire l'histoire d'une
 * commande déjà passée.
 */
export type OrderLine = $Result.DefaultSelection<Prisma.$OrderLinePayload>
/**
 * Model PaymentMethodConfig
 * 
 */
export type PaymentMethodConfig = $Result.DefaultSelection<Prisma.$PaymentMethodConfigPayload>
/**
 * Model Payment
 * 
 */
export type Payment = $Result.DefaultSelection<Prisma.$PaymentPayload>
/**
 * Model PaymentEvent
 * Journal brut de tout ce que l'agrégateur envoie ou répond. Preuve, base de
 * rejeu et matière du rapprochement quotidien.
 */
export type PaymentEvent = $Result.DefaultSelection<Prisma.$PaymentEventPayload>
/**
 * Model Refund
 * Règle du cahier client : le remboursement porte sur 100 % du prix produit.
 * Les frais de livraison et la commission Ojà restent acquis.
 */
export type Refund = $Result.DefaultSelection<Prisma.$RefundPayload>
/**
 * Model LedgerAccount
 * 
 */
export type LedgerAccount = $Result.DefaultSelection<Prisma.$LedgerAccountPayload>
/**
 * Model LedgerTransaction
 * Partie double stricte : la somme des montants signés d'une transaction vaut
 * exactement zéro. Aucune ligne n'est jamais modifiée ni supprimée — on
 * contre-passe. Garanti en base par un trigger, pas seulement par le code.
 */
export type LedgerTransaction = $Result.DefaultSelection<Prisma.$LedgerTransactionPayload>
/**
 * Model LedgerEntry
 * 
 */
export type LedgerEntry = $Result.DefaultSelection<Prisma.$LedgerEntryPayload>
/**
 * Model PayoutBatch
 * 
 */
export type PayoutBatch = $Result.DefaultSelection<Prisma.$PayoutBatchPayload>
/**
 * Model PayoutItem
 * 
 */
export type PayoutItem = $Result.DefaultSelection<Prisma.$PayoutItemPayload>
/**
 * Model DeliveryRun
 * Tournée : plusieurs missions groupées et confiées à un même livreur.
 * Le cahier client confie la création des tournées à l'administrateur.
 */
export type DeliveryRun = $Result.DefaultSelection<Prisma.$DeliveryRunPayload>
/**
 * Model Shipment
 * 
 */
export type Shipment = $Result.DefaultSelection<Prisma.$ShipmentPayload>
/**
 * Model ShipmentEvent
 * 
 */
export type ShipmentEvent = $Result.DefaultSelection<Prisma.$ShipmentEventPayload>
